SELECT  FROM tb_cls_item
WHERE tenant_id = #{tenantId}
ORDER BY upper_item_cls_id NULLS FIRST, sort_seq, item_cls_id

SELECT  FROM tb_cls_partner
WHERE tenant_id = #{tenantId}
ORDER BY upper_partner_cls_id NULLS FIRST, sort_seq, partner_cls_id

SELECT  FROM tb_cls_item
WHERE tenant_id = #{tenantId} AND item_cls_id = #{id}
FOR UPDATE

SELECT  FROM tb_cls_partner
WHERE tenant_id = #{tenantId} AND partner_cls_id = #{id}
FOR UPDATE
